"""Private bounded 7TA3 rigid-fragment control, generated by build_kernel.py."""

import base64
import hashlib
import json
import os
import platform
import subprocess
import sys
import tempfile
import urllib.request
import zlib
from pathlib import Path

PAYLOAD: dict[str, str]

EXPECTED = {
    "assets/tnf-peptide/7ta3.pdb": (
        "3c90d11838c88ebb5501319b367c6ac89e16c67c9a84aa22d17d5a4708052de4"
    ),
    "assets/tnf-peptide/receptor.pdbqt": (
        "ef6112549c988297f3911490d9a5466cfcb9fbce65c262608f1b4963e7785e06"
    ),
    "assets/tnf-peptide/reference.pdbqt": (
        "5cd3024fd227adcd1309a51faef8eedcb878de407dc5a76ea4b05251ad6d437e"
    ),
    "scripts/long_peptide_7ta3_control.py": (
        "ab2babb9d35b821f557952577279dbe482780b9ded9653721bd6f49696c4843b"
    ),
}
URL = (
    "https://github.com/ccsb-scripps/AutoDock-Vina/releases/download/v1.2.7/vina_1.2.7_linux_x86_64"
)


def main():
    root = Path(tempfile.mkdtemp(prefix="bioops-7ta3-"))
    if set(PAYLOAD) != set(EXPECTED):  # noqa: F821
        raise ValueError("unexpected payload members")
    for name, encoded in PAYLOAD.items():  # noqa: F821
        data = zlib.decompress(base64.b64decode(encoded, validate=True))
        if hashlib.sha256(data).hexdigest() != EXPECTED[name]:
            raise ValueError("payload hash mismatch: " + name)
        path = root / name
        path.parent.mkdir(parents=True, exist_ok=True)
        path.write_bytes(data)
    override = os.environ.get("BIOOPS_VINA")
    if override:
        vina = Path(override).resolve()
    else:
        if platform.system() != "Linux" or platform.machine() != "x86_64":
            raise RuntimeError("official binary requires Linux x86_64")
        vina = root / "vina"
        with urllib.request.urlopen(URL, timeout=90) as response:
            binary = response.read(20_000_001)
        if len(binary) > 20_000_000:
            raise ValueError("binary exceeds limit")
        vina.write_bytes(binary)
        vina.chmod(0o755)
    version = subprocess.run(
        [str(vina), "--version"], capture_output=True, text=True, check=True, timeout=15
    ).stdout.strip()
    if "1.2.7" not in version:
        raise ValueError("unexpected Vina version: " + version)
    out = Path(os.environ.get("BIOOPS_OUTPUT", "/kaggle/working/7ta3-control"))
    subprocess.run(
        [
            sys.executable,
            str(root / "scripts/long_peptide_7ta3_control.py"),
            "--vina",
            str(vina),
            "--output-dir",
            str(out),
        ],
        check=True,
        timeout=600,
    )
    report = json.loads((out / "report.json").read_text())
    report["runtime"] = {
        "platform": platform.platform(),
        "python": sys.version,
        "binary_url": URL if not override else "local smoke override",
        "binary_hash_verified_against_publisher": False,
        "kernel_sha256": hashlib.sha256(Path(__file__).read_bytes()).hexdigest(),
    }
    (out / "report.json").write_text(json.dumps(report, indent=2) + "\n")
    if not report["docking"]["poses"] or report["atom_count"] != 97:
        raise ValueError("QC failed: missing poses or wrong atom count")
    print("QC: 97 mapped atoms; poses:", len(report["docking"]["poses"]))


if __name__ == "__main__":
    main()
